class OverlayController {
  deps;
  constructor(deps) {
    this.deps = deps;
  }
  async open() {
    const plan2 = overlayPlan(this.deps.viewport(), this.deps.drawerOpen());
    if (plan2.closeDrawer && !await this.deps.closeDrawer()) {
      this.deps.inDrawer();
      return "drawer";
    }
    this.deps.surface.show(plan2.fullscreen);
    return "float";
  }
  close() {
    this.deps.surface.hide();
  }
  toggle() {
    if (!this.deps.surface.isVisible())
      return this.open();
    this.close();
    return Promise.resolve(null);
  }
}

